begin;
create function pg_temp.assert_true(ok boolean,message text) returns text language plpgsql as $$begin if ok is distinct from true then raise exception 'ASSERTION FAILED: %',message;end if;return message;end$$;
create function pg_temp.expect_error(query text,code text) returns boolean language plpgsql as $$begin execute query;return false;exception when others then if sqlstate<>code then raise exception 'Expected %, got %: %',code,sqlstate,sqlerrm;end if;return true;end$$;
create temporary table typed_definition(definition jsonb);grant select on typed_definition to authenticated;
insert into typed_definition values('{"fields":[{"key":"safe","type":"boolean","required":true},{"key":"reading","type":"number","required":true,"validation":{"minimum":1,"maximum":10}},{"key":"description","type":"text","required":true,"validation":{"min_length":3,"max_length":20}},{"key":"choice","type":"single_choice","required":true,"choices":["a","b"]},{"key":"extras","type":"multiple_choice","required":true,"choices":["a","b"]},{"key":"condition","type":"text","required":true,"condition":{"field":"safe","operator":"equals","value":true}}]}');
select app_private.validate_execution_answers((select definition from typed_definition),'{"safe":false,"reading":5,"description":"Clean","choice":"a","extras":["a"]}');
select pg_temp.assert_true(true,'All supported checklist answer types validate with exact condition semantics');
select pg_temp.assert_true(pg_temp.expect_error($q$select app_private.validate_execution_answers((select definition from typed_definition),'{"safe":false,"reading":5,"description":"Clean","choice":"a","extras":["a"],"condition":"Hidden"}')$q$,'23514'),'Hidden checklist answers are rejected');
select pg_temp.assert_true(pg_temp.expect_error($q$select app_private.validate_execution_answers((select definition from typed_definition),'{"safe":true,"reading":5,"description":"Clean","choice":"a","extras":["a"]}')$q$,'23514'),'Visible conditional required answers cannot be omitted');
select pg_temp.assert_true(pg_temp.expect_error($q$select app_private.validate_execution_answers((select definition from typed_definition),'{"safe":false,"reading":"5","description":"Clean","choice":"a","extras":["a"]}')$q$,'23514'),'Numeric measurements reject incorrectly typed answers');
select pg_temp.assert_true(pg_temp.expect_error($q$select app_private.validate_execution_answers((select definition from typed_definition),'{"safe":false,"reading":11,"description":"Clean","choice":"a","extras":["a"]}')$q$,'23514'),'Measurement bounds are enforced');
select pg_temp.assert_true(pg_temp.expect_error($q$select app_private.validate_execution_answers((select definition from typed_definition),'{"safe":false,"reading":5,"description":"xx","choice":"a","extras":["a"]}')$q$,'23514'),'Text validation bounds are enforced');
select pg_temp.assert_true(pg_temp.expect_error($q$select app_private.validate_execution_answers((select definition from typed_definition),'{"safe":false,"reading":5,"description":"Clean","choice":"other","extras":["a"]}')$q$,'23514'),'Unknown controlled choices are rejected');
select pg_temp.assert_true(pg_temp.expect_error($q$select app_private.validate_execution_answers((select definition from typed_definition),'{"safe":false,"reading":5,"description":"Clean","choice":"a","extras":["a","a"]}')$q$,'23514'),'Duplicate selectable choices are rejected');
select pg_temp.assert_true(pg_temp.expect_error($q$select app_private.validate_execution_answers((select definition from typed_definition),'{"safe":false,"reading":5,"description":"Clean","choice":"a","extras":["a"],"unknown":true}')$q$,'23514'),'Unknown checklist answer fields are rejected');
select pg_temp.assert_true(pg_temp.expect_error($q$update public.service_checklist_items set label='Changed' where checklist_id=(select id from public.service_checklists where code='synthetic-execution')$q$,'55000'),'Published execution standards cannot be rewritten');
select pg_temp.assert_true(pg_temp.expect_error($q$update private.execution_submissions set answers='{}' where status='approved'$q$,'55000'),'Approved checklist answers retain their original evidence');
select pg_temp.assert_true(pg_temp.expect_error($q$update private.execution_evidence set customer_visible=false where status='approved'$q$,'55000'),'Reviewed evidence visibility is immutable');
select pg_temp.assert_true(pg_temp.expect_error($q$update private.quality_findings set description='Changed'$q$,'55000'),'Defect findings are append-only');
select pg_temp.assert_true(pg_temp.expect_error($q$update private.customer_confirmations set decision='confirmed' where decision='disputed'$q$,'55000'),'Customer disputes cannot be overwritten by later sign-off');
select pg_temp.assert_true(pg_temp.expect_error($q$update public.customer_feedback set rating=1 where work_order_id is not null$q$,'55000'),'Feedback corrections require a retained new revision');
select pg_temp.assert_true(not has_table_privilege('authenticated','private.work_tasks','UPDATE') and not has_table_privilege('authenticated','private.quality_inspections','INSERT'),'Authenticated callers cannot bypass lifecycle commands');
select pg_temp.assert_true(not has_function_privilege('authenticated','app_private.pre_execution_dispatch_command(uuid,text,jsonb,text)','EXECUTE'),'Legacy dispatch helper cannot release active execution capacity');
select pg_temp.assert_true(not has_function_privilege('authenticated','app_private.pre_execution_order_command(uuid,text,jsonb,text)','EXECUTE'),'Legacy order helper cannot bypass fulfilment gates');
select pg_temp.assert_true((select bool_and(relrowsecurity) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private') and c.relkind='r'),'RLS remains enabled on every application table');
create temporary table configuration_ids(id uuid);insert into configuration_ids select id from private.fulfilment_policies where version=1;grant select on configuration_ids to authenticated;
grant execute on function pg_temp.assert_true(boolean,text),pg_temp.expect_error(text,text) to authenticated;
set local role authenticated;select set_config('request.jwt.claim.sub','d1000000-0000-0000-0000-000000000004',true);
select pg_temp.assert_true(public.read_fulfilment_configuration((select id from configuration_ids limit 1))->>'kind'='policy','Independent approver can inspect the complete configuration before deciding');
select pg_temp.assert_true(public.read_fulfilment_configuration((select id from configuration_ids limit 1))->'execution_checklist'->'fields' @> '[{"key":"done","type":"boolean"}]','Configuration read includes pinned existing checklist standards');
select set_config('request.jwt.claim.sub','a1000000-0000-0000-0000-000000000001',true);
select pg_temp.assert_true(pg_temp.expect_error($q$select public.read_fulfilment_configuration((select id from configuration_ids limit 1))$q$,'42501'),'Customers cannot inspect internal workflow and corporate SLA configuration');
reset role;
select pg_temp.assert_true(not has_function_privilege('anon','public.read_fulfilment_configuration(uuid)','EXECUTE'),'Anonymous configuration execution remains denied');
rollback;
